%[text] # LCC Trap Calculations
%[text] ## Functions & Variables
sympref('FloatingPointOutput',true);
close all;
%[text] ### Initialize Variables
%[text] Constants
u0 = 4*pi*10^-7; % permeability of free space
%[text] Frequency for each nuclei of interest
f_hf  = 123.2030E6; % Hz
f_lf = 49.8719E6; % Hz

w_hf = 2*pi*f_hf; % rad/s
w_lf = 2*pi*f_lf; % rad/s
%[text] ### Define Functions
%[text] Resonance of an LC circuit
syms f_LC(L,C)
f_LC(L,C) = 1/(2*pi*sqrt(L*C)) % Hz %[output:869b28fb]
%[text] Reactance of a capacitor
syms X_C(w,C)
X_C(w,C) = -1/(w*C) % Ohms %[output:01726631]
%[text] Reactance of an inductor
syms X_L(w,L)
X_L(w,L) = w*L % Ohms %[output:1076282a]
%[text] Inductance of HP birdcage 
syms L_bc(w,C,N)
L_bc(w,C,N) = 1/(4*w^2*C*(sin(pi/(2*N)))^2) % Henries %[output:11f41c69]
%[text] Trap inductance equation
syms L_tr(w,C)
L_tr(w,C) = 1/(C*w^2) % Henries %[output:86305244]
%[text] Tuning trap capacitance equation
syms C_t(w,L_c)
C_t(w,L_c) = 1/L_c*(w^2/(w_lf^2*w_hf^2)) % Farads %[output:499c6ba0]
%[text] Resonant trap capacitance equation for series resonant
syms C_r_s(w,L_c)
C_r_s(w,L_c) = 1/L_c*((w^2-w_lf^2)*(w_hf^2-w^2)/(w^2*w_lf^2*w_hf^2)) % Farads %[output:672fbe89]
%[text] Resonant trap capacitance equation for parallel resonant
syms C_r_p(w,L_c)
C_r_p(w,L_c) = 1/L_c*w^2/((w^2-w_lf^2)*(w_hf^2-w^2)) % Farads %[output:7ef35ad7]
%[text] Clear symbolic variables
clear w C L L_c
%%
%[text] ## Experimental Data
%[text] ### Inputs
%[text] Coil inductance calculations
Cexp = 47e-12; % Capacitance at each trap location to tune coil
N = 12 % Number of rungs %[output:2569d0c8]
Lcoil = L_bc(w_hf,Cexp,N) % Coil inductance %[output:6def822d]
%[text] ### Testing
close all
%[text] Testing ranges
w = (ceil(f_lf/1e6):0.5:floor(f_hf/1e6)).*(2*pi*1e6);
Lmax = 500/w_hf %[output:7e14d7ee]
%[text] #### Plots
figure; plot(w./(2*pi*1e6), C_r_s(w,Lcoil)*1e12,'black','DisplayName','C_{s}','LineStyle','--'); xlabel('MHz');ylabel('pF'); xlim([min(w)/(2*pi*1E6) max(w)/(2*pi*1E6)]); title('Series Resonant') %[output:3e1bad4e]
hold on; plot(w./(2*pi*1e6), C_t(w,Lcoil)*1e12,'black','DisplayName','C_{p}'); hold off %[output:3e1bad4e]
figure; plot(w./(2*pi*1e6), L_tr(w,C_r_s(w,Lcoil))*1e9,'black','DisplayName','L_{tr}'); xlabel('MHz');ylabel('nH'); xlim([min(w)/(2*pi*1E6) max(w)/(2*pi*1E6)]); ylim([0 Lmax*1e9]); title('Series Resonant') %[output:132c8a61]

figure; plot(w./(2*pi*1e6), C_r_p(w,Lcoil)*1e12,'black','DisplayName','C_{s}','LineStyle','--'); xlabel('MHz');ylabel('pF'); xlim([min(w)/(2*pi*1E6) max(w)/(2*pi*1E6)]); title('Parallel Resonant') %[output:3804b278]
hold on; plot(w./(2*pi*1e6), C_t(w,Lcoil)*1e12,'black','DisplayName','C_{p}'); hold off; if max(C_r_p(w,Lcoil)*1e12)>40, ylim([0 40]); end %[output:3804b278]
figure; plot(w./(2*pi*1e6), L_tr(w,C_r_p(w,Lcoil))*1e9,'black','DisplayName','L_{tr}'); xlabel('MHz');ylabel('nH'); xlim([min(w)/(2*pi*1E6) max(w)/(2*pi*1E6)]); ylim([0 Lmax*1e9]); title('Parallel Resonant') %[output:42f51bae]

